:var(--text-dim);margin-top:.2rem}.guide-reference{display:grid;gap:.4rem;border-top:1px solid var(--line-soft);padding-top:.8rem;margin-top:1rem;font-size:.61rem;color:var(--text-dim)}.guide-reference a{color:var(--gold-dim);overflow-wrap:anywhere}.activity-expand:focus-visible,.activity-filters button:focus-visible{outline:2px solid var(--gold)}
@media(max-width:760px){.activity-detail{display:block}.activity-list{grid-template-columns:1fr}.activity-heading{align-items:start;flex-direction:column}.activity-card{padding:1rem}}
@media(max-width:390px){.activity-rewards{grid-template-columns:1fr}}
</style>

<style scoped>
.reward-placeholder{display:grid;place-items:center;width:2.2rem;height:2.2rem;flex-shrink:0;background:rgba(232,193,90,.05);color:var(--gold-dim);font-style:normal}.en-tag{display:block;color:var(--gold-dim);font:.58rem var(--font-en);letter-spacing:.1em;overflow-wrap:anywhere}.team-size{max-width:6.5rem;white-space:normal;flex-shrink:0}.activity-tags .archive-tag{color:var(--gold-bright);background:rgba(232,193,90,.1)}.guide-gap{font-size:.73rem;line-height:1.8;padding:.6rem .75rem;background:rgba(232,193,90,.06);color:var(--text-sub)}.guide-gap strong{color:var(--gold-bright);margin-right:.5rem}.reward-scope{font-size:.68rem!important;color:var(--text-dim)!important}.guide-reference p{margin:0;font-size:.72rem}.guide-reference strong{color:var(--gold-dim);margin-right:.5rem}.reference-meta,.reference-row{display:flex;flex-wrap:wrap;gap:.5rem 1rem;justify-content:space-between}.reference-meta{margin:.35rem 0}.activity-expand{font-family:inherit}.activity-expand:focus-visible{outline-offset:3px}@media(max-width:760px){.reference-meta,.reference-row{display:grid}}
</style>
